    await mysqlConn().query("CREATE TABLE IF NOT EXISTS biz_alert (\n  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键',\n  tenant_id BIGINT DEFAULT 0 COMMENT '租户ID（0=平台）',\n  alert_type TINYINT NOT NULL COMMENT '1到期 2超授权 3未登记 4未核查',\n  biz_type TEXT(30) COMMENT '关联业务类型（entitlement/computer/software）',\n  biz_id BIGINT DEFAULT 0 COMMENT '关联业务ID',\n  level TINYINT DEFAULT 2 COMMENT '预警级别：1高 2中 3低',\n  content TEXT(500) NOT NULL COMMENT '预警内容',\n  org_id BIGINT DEFAULT 0 COMMENT '归属单位',\n  status TINYINT DEFAULT 0 COMMENT '0未处理 1处理中 2已处理',\n  handler_id BIGINT DEFAULT 0 COMMENT '处理人',\n  handle_time DATETIME COMMENT '处理时间',\n  handle_remark TEXT(500) COMMENT '处理说明',\n  create_time DATETIME COMMENT '创建时间',\n  update_time DATETIME COMMENT '更新时间',\n  create_by BIGINT COMMENT '创建人',\n  update_by BIGINT COMMENT '更新人',\n  is_deleted TINYINT DEFAULT 0 COMMENT '逻辑删除标志'\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='预警表（FR-12：1到期 2超授权 3未登记 4未核查）'")
    try { await mysqlConn().query("CREATE INDEX idx_biz_alert_alert_type ON biz_alert (alert_type)") } catch (e) { if (!/exist|duplicate/i.test(String(e.message))) throw e }
